local_input_backups.content:
[release]
remote_effects = "github"
hosted_workflow = ".github/workflows/release.yml"
aliases = { cargo-rail-action = "v10" }
validation = { ".github/workflows/package.yml" = ["Check / aarch64-apple-darwin", "Check / aarch64-unknown-linux-gnu", "Check / x86_64-pc-windows-msvc", "Check / x86_64-unknown-linux-gnu", "Collect release assets"] }

[release.artifacts.cargo-rail-action]
workflow = ".github/workflows/package.yml"
[release.artifacts.cargo-rail-action.files]
"cargo-rail-action-aarch64-apple-darwin" = { target = "aarch64-apple-darwin" }
"cargo-rail-action-aarch64-unknown-linux-gnu" = { target = "aarch64-unknown-linux-gnu" }
"cargo-rail-action-x86_64-pc-windows-msvc.exe" = { target = "x86_64-pc-windows-msvc" }
"cargo-rail-action-x86_64-unknown-linux-gnu" = { target = "x86_64-unknown-linux-gnu" }
"cargo-rail-action-runtime-v1.tsv" = {}
"LICENSE" = { source = "LICENSE" }
